import{_ as t,o as a,c as i,a5 as n}from"./chunks/framework.a5no_H3L.js";const o=JSON.parse('{"title":"可观测性","description":"核心问题：日志、指标、链路追踪三大支柱如何落地？如何快速定位线上问题？","frontmatter":{},"headers":[],"relativePath":"engineering/06-engineering-practices/chapter-06-observability.md","filePath":"engineering/06-engineering-practices/chapter-06-observability.md"}'),r={name:"engineering/06-engineering-practices/chapter-06-observability.md"};function l(s,e,c,g,d,p){return a(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="可观测性" tabindex="-1" data-src-line="1" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md">可观测性 <a class="header-anchor" href="#可观测性" aria-label="Permalink to &quot;可观测性&quot;">​</a></h1><blockquote data-src-line="3" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md"><p data-src-line="3" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md"><strong>核心问题</strong>：日志、指标、链路追踪三大支柱如何落地？如何快速定位线上问题？</p></blockquote><h2 id="_1-可观测性三大支柱" tabindex="-1" data-src-line="5" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md">1. 可观测性三大支柱 <a class="header-anchor" href="#_1-可观测性三大支柱" aria-label="Permalink to &quot;1. 可观测性三大支柱&quot;">​</a></h2><table tabindex="0"><thead data-src-line="7" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md"><tr data-src-line="7" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md"><th style="text-align:left;">支柱</th><th style="text-align:left;">回答的问题</th><th style="text-align:left;">工具</th></tr></thead><tbody data-src-line="9" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md"><tr data-src-line="9" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md"><td style="text-align:left;">日志（Logging）</td><td style="text-align:left;">发生了什么？</td><td style="text-align:left;">ELK、Loki</td></tr><tr data-src-line="10" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md"><td style="text-align:left;">指标（Metrics）</td><td style="text-align:left;">系统状态如何？</td><td style="text-align:left;">Prometheus、Grafana</td></tr><tr data-src-line="11" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md"><td style="text-align:left;">链路追踪（Tracing）</td><td style="text-align:left;">请求经过了哪些服务？</td><td style="text-align:left;">SkyWalking、Jaeger</td></tr></tbody></table><p data-src-line="13" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md">三者各有侧重，日志提供细节，指标提供全局视图，链路追踪提供调用路径。它们不是靠同一个 TraceID 直接串联，而是两两之间采用不同的关联方式。日志与追踪通过 TraceID、SpanID 关联。指标与追踪通过服务、接口等维度定位问题，再借助追踪系统的查询能力或 Exemplars 跳转到具体 Trace。日志与指标通过服务、实例、接口、时间窗口等共同维度关联。</p><h2 id="_2-结构化日志" tabindex="-1" data-src-line="15" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md">2. 结构化日志 <a class="header-anchor" href="#_2-结构化日志" aria-label="Permalink to &quot;2. 结构化日志&quot;">​</a></h2><p data-src-line="17" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md">结构化日志的核心：用 JSON 等可解析格式输出，并携带请求上下文（如 userId、traceId），便于 ELK 检索。生产环境还需守住边界，只记录排障所需的上下文，优先使用非敏感业务标识，不记录密码、访问令牌等敏感信息，并对日志字段统一命名、脱敏和设保留策略，避免将高基数字段无差别地设为索引字段或标签。</p><blockquote data-src-line="19" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md"><p data-src-line="19" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md">各框架的结构化日志落地（MDC、Logback 配置）见 <a href="./../../spring/06-observability/chapter-01-logging.html">Spring 日志</a>。</p></blockquote><h2 id="_3-指标监控" tabindex="-1" data-src-line="21" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md">3. 指标监控 <a class="header-anchor" href="#_3-指标监控" aria-label="Permalink to &quot;3. 指标监控&quot;">​</a></h2><p data-src-line="23" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md">指标监控的核心：采集 QPS、响应时间、错误率、资源使用率等时间序列数据，配合告警规则及时发现异常。</p><blockquote data-src-line="25" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md"><p data-src-line="25" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md">Micrometer 与 Actuator 的指标暴露见 <a href="./../../spring/06-observability/chapter-02-metrics.html">Spring 指标</a>。</p></blockquote><h2 id="_4-链路追踪" tabindex="-1" data-src-line="27" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md">4. 链路追踪 <a class="header-anchor" href="#_4-链路追踪" aria-label="Permalink to &quot;4. 链路追踪&quot;">​</a></h2><p data-src-line="29" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md">链路追踪的核心：为请求建立 Trace 上下文，并在支持追踪的调用链中传播 TraceID，定位慢请求与错误传播路径。实际能否查到完整 Trace，取决于埋点、上下文传播和采样配置。</p><blockquote data-src-line="31" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md"><p data-src-line="31" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md">SkyWalking / OpenTelemetry 的接入见 <a href="./../../spring/06-observability/chapter-03-tracing.html">Spring 链路追踪</a>。</p></blockquote><h2 id="_5-监控体系设计" tabindex="-1" data-src-line="33" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md">5. 监控体系设计 <a class="header-anchor" href="#_5-监控体系设计" aria-label="Permalink to &quot;5. 监控体系设计&quot;">​</a></h2><table tabindex="0"><thead data-src-line="35" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md"><tr data-src-line="35" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md"><th style="text-align:left;">层次</th><th style="text-align:left;">监控内容</th><th style="text-align:left;">示例阈值</th></tr></thead><tbody data-src-line="37" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md"><tr data-src-line="37" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md"><td style="text-align:left;">基础设施</td><td style="text-align:left;">CPU、内存、磁盘、网络</td><td style="text-align:left;">CPU &gt; 80%、内存 &gt; 90%</td></tr><tr data-src-line="38" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md"><td style="text-align:left;">应用层</td><td style="text-align:left;">QPS、响应时间、错误率</td><td style="text-align:left;">错误率 &gt; 5%、P99 &gt; 1s</td></tr><tr data-src-line="39" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md"><td style="text-align:left;">业务层</td><td style="text-align:left;">订单量、支付成功率</td><td style="text-align:left;">支付成功率 &lt; 95%</td></tr></tbody></table><blockquote data-src-line="41" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md"><p data-src-line="41" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md">表格中的阈值只是示例，不能直接当作通用生产标准。实际告警策略应围绕延迟、错误率和流量建立服务级目标（SLO），结合错误预算设计告警；基础设施告警要结合持续时间、资源限制和实际业务影响判断，避免仅凭瞬时利用率触发；业务指标要结合业务目标、统计窗口和有效样本量设置阈值。</p></blockquote><h2 id="_6-线上问题定位方法论" tabindex="-1" data-src-line="43" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md">6. 线上问题定位方法论 <a class="header-anchor" href="#_6-线上问题定位方法论" aria-label="Permalink to &quot;6. 线上问题定位方法论&quot;">​</a></h2><h3 id="_6-1-三板斧-日志、指标、链路" tabindex="-1" data-src-line="45" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md">6.1 三板斧：日志、指标、链路 <a class="header-anchor" href="#_6-1-三板斧-日志、指标、链路" aria-label="Permalink to &quot;6.1 三板斧：日志、指标、链路&quot;">​</a></h3><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>发现问题（告警、用户反馈、SLO 变化）</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ▼</span></span>
<span class="line"><span>界定影响范围（时间窗口、接口、实例、下游依赖）</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ▼</span></span>
<span class="line"><span>看指标（Grafana）确认问题范围和影响</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ├── 有可用 Trace ── 看链路（Jaeger/SkyWalking）定位到具体环节</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    └── 无可用 Trace ── 检查采样策略、指标、日志与运行时证据，不能把找不到慢 Trace 当作问题不存在</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ▼</span></span>
<span class="line"><span>看日志（Kibana）用 TraceID 或关键字定位异常堆栈</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ▼</span></span>
<span class="line"><span>验证假设并确认恢复，复现或交叉验证，观察指标与业务影响回归正常，不只凭单一指标就认定根因已解决</span></span></code></pre></div><blockquote data-src-line="67" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md"><p data-src-line="67" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md">上图是一条常用排查路径，不是必须严格执行的顺序。日志中已有明确异常堆栈时可直接从日志追查，CPU 飙高时线程栈和系统指标可能比 Trace 更有价值，按证据选择入口即可。</p></blockquote><h3 id="_6-2-常见问题排查路径" tabindex="-1" data-src-line="69" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md">6.2 常见问题排查路径 <a class="header-anchor" href="#_6-2-常见问题排查路径" aria-label="Permalink to &quot;6.2 常见问题排查路径&quot;">​</a></h3><table tabindex="0"><thead data-src-line="71" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md"><tr data-src-line="71" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md"><th style="text-align:left;">问题现象</th><th style="text-align:left;">排查步骤</th><th style="text-align:left;">常见根因</th></tr></thead><tbody data-src-line="73" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md"><tr data-src-line="73" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md"><td style="text-align:left;">接口响应变慢</td><td style="text-align:left;">看 P99 趋势 → 找慢 Trace → 定位慢在哪个环节 → 看该环节日志</td><td style="text-align:left;">慢 SQL、缓存穿透、下游超时、GC 暂停</td></tr><tr data-src-line="74" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md"><td style="text-align:left;">偶发 500 错误</td><td style="text-align:left;">看错误率分布 → 搜 ERROR 日志 → 看异常堆栈 → 关联 TraceID</td><td style="text-align:left;">空指针、参数校验异常处理不当、并发竞争、连接池耗尽</td></tr><tr data-src-line="75" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md"><td style="text-align:left;">内存泄漏</td><td style="text-align:left;">看堆内存趋势与 GC 情况 → 生成堆转储 → 分析大对象</td><td style="text-align:left;">大集合未清理、ThreadLocal 泄露、缓存无上限</td></tr><tr data-src-line="76" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md"><td style="text-align:left;">CPU 飙高</td><td style="text-align:left;">找高 CPU 进程 → 找高 CPU 线程 → 将线程 ID 转为十六进制按 nid 查找线程栈</td><td style="text-align:left;">死循环、频繁 Full GC、正则回溯</td></tr><tr data-src-line="77" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md"><td style="text-align:left;">数据库连接池耗尽</td><td style="text-align:left;">看活跃连接数 → 确认是否达上限 → 查慢 SQL → 查事务关闭</td><td style="text-align:left;">慢 SQL 占连接、事务未提交、连接泄漏</td></tr></tbody></table><blockquote data-src-line="79" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md"><p data-src-line="79" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md">JVM 诊断工具（jmap、jstack、Arthas）的用法见 <a href="./../../spring/06-observability/chapter-04-production-debug.html">Spring 生产排查</a>。</p></blockquote><blockquote data-src-line="81" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md"><p data-src-line="81" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md"><strong>核心原则</strong>：可观测性不是事后补充，而是从第一天就设计进去。</p></blockquote><h2 id="_7-本章小结" tabindex="-1" data-src-line="83" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md">7. 本章小结 <a class="header-anchor" href="#_7-本章小结" aria-label="Permalink to &quot;7. 本章小结&quot;">​</a></h2><p data-src-line="85" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md">可观测性三大支柱各司其职，又通过不同的关联方式协同工作。</p><table tabindex="0"><thead data-src-line="87" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md"><tr data-src-line="87" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md"><th style="text-align:left;">支柱</th><th style="text-align:left;">回答的问题</th><th style="text-align:left;">数据形态</th><th style="text-align:left;">代表技术栈</th></tr></thead><tbody data-src-line="89" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md"><tr data-src-line="89" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md"><td style="text-align:left;"><strong>日志</strong></td><td style="text-align:left;">发生了什么？</td><td style="text-align:left;">离散事件</td><td style="text-align:left;">Logback → Filebeat → Elasticsearch → Kibana</td></tr><tr data-src-line="90" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md"><td style="text-align:left;"><strong>指标</strong></td><td style="text-align:left;">整体状况如何？</td><td style="text-align:left;">时间序列数值</td><td style="text-align:left;">Micrometer → Prometheus → Grafana</td></tr><tr data-src-line="91" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md"><td style="text-align:left;"><strong>链路追踪</strong></td><td style="text-align:left;">请求经过了哪里？哪里慢？</td><td style="text-align:left;">调用树</td><td style="text-align:left;">OpenTelemetry → Collector → Jaeger/SkyWalking</td></tr></tbody></table><p data-src-line="93" data-src-file="engineering/06-engineering-practices/chapter-06-observability.md">三者不是互斥选择，而是互补关系。日志提供细节，指标提供全局视图，链路追踪提供调用路径。日志与追踪靠 TraceID、SpanID 关联，指标与追踪靠维度或 Exemplars 跳转，日志与指标靠共同维度关联，三者组合起来有助于形成更完整的可观测能力。</p>`,29)])])}const h=t(r,[["render",l]]);export{o as __pageData,h as default};
